import{_ as e,o,c as r,a2 as a}from"./chunks/framework.sN6AQ-fu.js";const u=JSON.parse('{"title":"Your first routine","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}'),s={name:"guide/quick-start.md"};function n(i,t,c,d,l,p){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="your-first-routine" tabindex="-1">Your first routine <a class="header-anchor" href="#your-first-routine" aria-label="Permalink to &quot;Your first routine&quot;">​</a></h1><p>Install the <a href="/Mayhem/guide/installation">desktop app</a>, or run the browser version from a checkout with <code>cd app &amp;&amp; pnpm install &amp;&amp; pnpm dev</code> and open <code>http://localhost:5173</code>. No Python solver or robot is needed.</p><ol><li>Click the project name in the top bar and create a project.</li><li>On <strong>Robot → Specs &amp; limits</strong>, enter the robot&#39;s size and drive limits, and add any typed inputs your routine will check (sensors, game state).</li><li>On <strong>Autonomous</strong>, create a routine and drag the starting robot into place.</li><li>Choose <strong>Pose</strong> (<code>W</code>), <strong>Any heading</strong> (<code>T</code>) or <strong>Pass through</strong> (<code>G</code>) and click the field to place goals, or <strong>Draw</strong> (<code>D</code>) the route freehand.</li><li>Select a step to set its heading, stop/handoff behavior and limits. Use <strong>Advanced</strong> for callbacks, conditions and watchdogs, and <strong>Whole path → Map → Generate</strong> to solve speed caps and corner radii.</li><li>Press <strong>Preview</strong> (Space). <strong>Path</strong> drives the route; <strong>With actions</strong> waits on your simulated inputs and callback results under <strong>Inputs &amp; events</strong>.</li><li>Check the badge above the field says <strong>Fits in auto</strong>, then export the C++ (Overview&#39;s match-ready checklist or <strong>Tasks → Connect an agent → C++ library</strong>) and register your callbacks in robot code.</li></ol><p><a href="/Mayhem/suite/autonomous">Everything in Autonomous →</a></p><p>Suite <code>.mayhem.json</code> projects are separate from classic <code>project.mayhem</code> / <code>.mtraj</code> projects. For the solver and Java MayhemLib workflow, follow the <a href="/Mayhem/guide/classic-quick-start">classic trajectory quick start</a>.</p>',5)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
